const input = document.getElementById('latex-input');
        const output = document.getElementById('math-preview');
        // Tab Switching
        function switchTab(tabName, btn) {
            document.querySelectorAll('[id^="palette-"]').forEach(el => el.classList.add('hidden'));
            document.getElementById(`palette-${tabName}`).classList.remove('hidden');
            document.querySelectorAll('.palette-tab').forEach(el => el.classList.remove('active'));
            btn.classList.add('active');
        }
        // Insert Command at Cursor
        function insertCmd(cmd) {
            const start = input.selectionStart;
            const end = input.selectionEnd;
            const text = input.value;
            const before = text.substring(0, start);
            const after = text.substring(end, text.length);
            input.value = before + cmd + after;
            input.selectionStart = input.selectionEnd = start + cmd.length;
            input.focus();
            renderMath();
        }
        // Render Function
        let mathJaxPromise = null;
        function ensureMathJax() {
            if (typeof MathJax !== 'undefined' && MathJax.tex2svgPromise) return Promise.resolve();
            if (mathJaxPromise) return mathJaxPromise;
            mathJaxPromise = new Promise((resolve, reject) => {
                const s = document.createElement('script');
                s.src = 'https://cdn.jsdelivr.net/npm/mathjax@3/es5/tex-svg.js';
                s.async = true;
                s.onload = () => resolve();
                s.onerror = reject;
                document.head.appendChild(s);
            });
            return mathJaxPromise;
        }

        async function renderMath() {
            output.innerHTML = '';
            const tex = input.value;
            if (!tex) return;
            try {
                await ensureMathJax();
                const options = MathJax.getMetricsFor(output);
                const node = await MathJax.tex2svgPromise(tex, options);
                output.appendChild(node);
                MathJax.startup.document.clear();
                MathJax.startup.document.updateDocument();
            } catch (err) {
                output.innerHTML = `<span class="text-red-500 text-[10px] font-mono font-bold uppercase tracking-widest">Syntax Compromised: ${err.message}</span>`;
            }
        }
        function clearEditor() {
            if (!confirm("Purge current syntax buffer?")) return;
            input.value = '';
            renderMath();
        }
        function copyCode() {
            navigator.clipboard.writeText(input.value).then(() => {
                showToast("LaTeX syntax copied to clipboard.");
            });
        }
        function downloadSVG() {
            const svg = output.querySelector('svg');
            if (!svg) return;
            const serializer = new XMLSerializer();
            let source = serializer.serializeToString(svg);
            if (!source.match(/^<svg[^>]+xmlns="http\:\/\/www\.w3\.org\/2000\/svg"/)) {
                source = source.replace(/^<svg/, '<svg xmlns="http://www.w3.org/2000/svg"');
            }
            const url = "data:image/svg+xml;charset=utf-8," + encodeURIComponent(source);
            const link = document.createElement("a");
            link.href = url;
            link.download = "equation_vector_export.svg";
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);
        }
        function showToast(msg) {
            const toast = document.createElement('div');
            toast.className = "fixed top-24 left-1/2 -translate-x-1/2 bg-slate-800 text-white px-8 py-3 rounded-full shadow-2xl z-[100] animate-bounce font-black text-xs uppercase tracking-widest";
            toast.innerText = msg;
            document.body.appendChild(toast);
            setTimeout(() => toast.remove(), 4000);
        }
        // Scroll to Top Logic
        input.addEventListener('input', renderMath);
        input.addEventListener('focus', renderMath, { once: true });
        if ('requestIdleCallback' in window) {
            requestIdleCallback(() => { if (typeof MathJax !== 'undefined' && MathJax.tex2svgPromise) renderMath(); });
        }
